    16→void USessionManager::Initialize()
    17→{
    18→	// Online Subsystem 가져오기 - 우선순위: Steam > NULL
    19→	IOnlineSubsystem* OnlineSubsystem = IOnlineSubsystem::Get(STEAM_SUBSYSTEM);
    20→	if (!OnlineSubsystem)
    21→	{
    22→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Steam subsystem not available, trying NULL subsystem"));
    23→		OnlineSubsystem = IOnlineSubsystem::Get(NULL_SUBSYSTEM);
    24→	}
    25→
    26→	if (OnlineSubsystem)
    27→	{
    28→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnlineSubsystem found - Name: %s"), *OnlineSubsystem->GetSubsystemName().ToString());
    29→
    30→		SessionInterface = OnlineSubsystem->GetSessionInterface();
    31→
    32→		if (SessionInterface.IsValid())
    33→		{
    34→			// 델리게이트 바인딩
    35→			SessionInterface->OnCreateSessionCompleteDelegates.AddUObject(this, &USessionManager::OnCreateSessionComplete);
    36→			SessionInterface->OnFindSessionsCompleteDelegates.AddUObject(this, &USessionManager::OnFindSessionsComplete);
    37→			SessionInterface->OnJoinSessionCompleteDelegates.AddUObject(this, &USessionManager::OnJoinSessionComplete);
    38→			SessionInterface->OnDestroySessionCompleteDelegates.AddUObject(this, &USessionManager::OnDestroySessionComplete);
    39→			SessionInterface->OnStartSessionCompleteDelegates.AddUObject(this, &USessionManager::OnStartSessionComplete);
    40→			SessionInterface->OnEndSessionCompleteDelegates.AddUObject(this, &USessionManager::OnEndSessionComplete);
    41→
    42→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Initialized successfully with %s"), *OnlineSubsystem->GetSubsystemName().ToString());
    43→		}
    44→		else
    45→		{
    46→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to get SessionInterface from %s"), *OnlineSubsystem->GetSubsystemName().ToString());
    47→		}
    48→	}
    49→	else
    50→	{
    51→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: No OnlineSubsystem available (Steam and NULL both failed)"));
    52→	}
    53→}
    54→
    55→void USessionManager::Shutdown()
    56→{
    57→	if (SessionInterface.IsValid())
    58→	{
    59→		// 델리게이트 언바인딩
    60→		SessionInterface->OnCreateSessionCompleteDelegates.RemoveAll(this);
    61→		SessionInterface->OnFindSessionsCompleteDelegates.RemoveAll(this);
    62→		SessionInterface->OnJoinSessionCompleteDelegates.RemoveAll(this);
    63→		SessionInterface->OnDestroySessionCompleteDelegates.RemoveAll(this);
    64→		SessionInterface->OnStartSessionCompleteDelegates.RemoveAll(this);
    65→		SessionInterface->OnEndSessionCompleteDelegates.RemoveAll(this);
    66→
    67→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Shutdown"));
    68→	}
    69→}
