    71→void USessionManager::ApplyNetDriverForMode(ENetworkMode Mode)
    72→{
    73→	if (!GEngine) return;
    74→
    75→	for (FNetDriverDefinition& Def : GEngine->NetDriverDefinitions)
    76→	{
    77→		if (Def.DefName == FName(TEXT("GameNetDriver")))
    78→		{
    79→			if (Mode == ENetworkMode::LAN)
    80→			{
    81→				// SocketSubsystemSteamIP가 기본 소켓을 Steam으로 오버라이드하므로
    82→				// IpNetDriver 대신 WjWorldLanNetDriver 사용 (PLATFORM_SOCKETSUBSYSTEM 명시)
    83→				Def.DriverClassName = FName(TEXT("/Script/WjWorld.WjWorldLanNetDriver"));
    84→				Def.DriverClassNameFallback = FName(TEXT("/Script/OnlineSubsystemUtils.IpNetDriver"));
    85→			}
    86→			else // Steam
    87→			{
    88→				Def.DriverClassName = FName(TEXT("/Script/SocketSubsystemSteamIP.SteamNetDriver"));
    89→				Def.DriverClassNameFallback = FName(TEXT("/Script/OnlineSubsystemUtils.IpNetDriver"));
    90→			}
    91→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: NetDriver set to '%s' for %s mode"),
    92→				*Def.DriverClassName.ToString(),
    93→				Mode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
    94→			break;
    95→		}
    96→	}
    97→}
