   188→bool USessionManager::FindSessions(ENetworkMode NetworkMode, int32 MaxSearchResults)
   189→{
   190→	if (!SessionInterface.IsValid())
   191→	{
   192→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   193→		return false;
   194→	}
   195→
   196→	// 이전 검색이 진행 중이면 대기열에 등록 (완료 후 자동 실행)
   197→	if (bIsSearchInProgress)
   198→	{
   199→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Previous search in progress, queuing new %s search"),
   200→			NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   201→		PendingSearchRequest = TPair<ENetworkMode, int32>(NetworkMode, MaxSearchResults);
   202→		return true;
   203→	}
   204→
   205→	// 검색 네트워크 모드 저장 (JoinSession에서 NetDriver 전환용)
   206→	LastSearchNetworkMode = NetworkMode;
   207→
   208→	// 검색 설정
   209→	SessionSearch = MakeShareable(new FOnlineSessionSearch());
   210→	SessionSearch->MaxSearchResults = MaxSearchResults;
   211→
   212→	// 네트워크 모드에 따른 검색 설정
   213→	if (NetworkMode == ENetworkMode::Steam)
   214→	{
   215→		SessionSearch->bIsLanQuery = false;
   216→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, true, EOnlineComparisonOp::Equals);
   217→	}
   218→	else // LAN
   219→	{
   220→		SessionSearch->bIsLanQuery = true;
   221→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, false, EOnlineComparisonOp::Equals);
   222→	}
   223→
   224→	// 검색 시작
   225→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   226→	bool bSuccess = SessionInterface->FindSessions(*LocalPlayer->GetPreferredUniqueNetId(), SessionSearch.ToSharedRef());
   227→
   228→	if (bSuccess)
   229→	{
   230→		bIsSearchInProgress = true;
   231→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Searching for %s sessions..."),
   232→			NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   233→	}
   234→	else
   235→	{
   236→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to start session search"));
   237→	}
   238→
   239→	return bSuccess;
   240→}
