   488→void USessionManager::OnJoinSessionComplete(FName SessionName, EOnJoinSessionCompleteResult::Type Result)
   489→{
   490→	bool bWasSuccessful = (Result == EOnJoinSessionCompleteResult::Success);
   491→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnJoinSessionComplete - Success: %d, Result: %d"), bWasSuccessful, (int32)Result);
   492→
   493→	if (bWasSuccessful)
   494→	{
   495→		bIsInSession = true;
   496→
   497→		if (SessionInterface.IsValid())
   498→		{
   499→			FString ConnectInfo;
   500→			SessionInterface->GetResolvedConnectString(SessionName, ConnectInfo);
   501→
   502→			UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: GetResolvedConnectString returned: '%s'"), *ConnectInfo);
   503→
   504→			// ⭐ 포트가 0이면 7777로 교체
   505→			if (ConnectInfo.Contains(TEXT(":0")))
   506→			{
   507→				// IP 주소 추출 (":"앞부분)
   508→				FString IPAddress;
   509→				FString PortString;
   510→
   511→				if (ConnectInfo.Split(TEXT(":"), &IPAddress, &PortString))
   512→				{
   513→					// 올바른 포트로 재조립
   514→					ConnectInfo = IPAddress + TEXT(":7777");
   515→					UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Fixed ConnectInfo: %s"), *ConnectInfo);
   516→				}
   517→				else
   518→				{
   519→					// Split 실패 시 Fallback
   520→					ConnectInfo = TEXT("127.0.0.1:7777");
   521→					UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Using fallback: %s"), *ConnectInfo);
   522→				}
   523→			}
   524→
   525→			// 검색 시 사용한 네트워크 모드에 맞게 NetDriver 전환
   526→			ApplyNetDriverForMode(LastSearchNetworkMode);
   527→
   528→			APlayerController* PC = GetWorld()->GetFirstPlayerController();
   529→			if (PC && !ConnectInfo.IsEmpty())
   530→			{
   531→				UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Traveling to: %s"), *ConnectInfo);
   532→				PC->ClientTravel(ConnectInfo, ETravelType::TRAVEL_Absolute);
   533→			}
   534→			else
   535→			{
   536→				UE_LOG(LogWjWorld, Error, TEXT("SessionManager: ConnectInfo is empty or PC is null"));
   537→			}
   538→		}
   539→	}
   540→
   541→	OnRoomJoinedEvent.Broadcast(bWasSuccessful);
   542→}
