   697→bool USessionManager::GetSessionPassword(int32 SearchResultIndex, FString& OutPassword) const
   698→{
   699→	OutPassword.Empty();
   700→
   701→	if (!SessionSearch.IsValid() || !SessionSearch->SearchResults.IsValidIndex(SearchResultIndex))
   702→	{
   703→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: GetSessionPassword - Invalid index %d"), SearchResultIndex);
   704→		return false;
   705→	}
   706→
   707→	const FOnlineSessionSearchResult& Result = SessionSearch->SearchResults[SearchResultIndex];
