   124→void URoomListWindow::UpdateRoomList(const TArray<FRoomInfo>& Rooms)
   125→{
   126→	if (!RoomListScrollBox)
   127→	{
   128→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListScrollBox is null"));
   129→		return;
   130→	}
   131→
   132→	if (!RoomListEntryWidgetClass)
   133→	{
   134→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListEntryWidgetClass is not set"));
   135→		return;
   136→	}
   137→
   138→	// 기존 목록 제거
   139→	RoomListScrollBox->ClearChildren();
   140→
   141→	// 방이 없으면 메시지 표시
   142→	if (Rooms.Num() == 0)
   143→	{
   144→		UE_LOG(LogWjWorld, Warning, TEXT("RoomListWindow: No rooms found"));
