   146→		return;
   147→	}
   148→
   149→	// 각 방에 대한 엔트리 위젯 생성
   150→	for (const FRoomInfo& RoomInfo : Rooms)
   151→	{
   152→		URoomListEntryWidget* EntryWidget = CreateWidget<URoomListEntryWidget>(GetWorld(), RoomListEntryWidgetClass);
   153→		if (EntryWidget)
   154→		{
   155→			EntryWidget->SetRoomInfo(RoomInfo);
   156→			RoomListScrollBox->AddChild(EntryWidget);
   157→		}
   158→	}
   159→
   160→	UE_LOG(LogWjWorld, Log, TEXT("RoomListWindow: Room list updated with %d entries"), Rooms.Num());
   161→}
