   276→void URoomListWindow::JoinRoomWithPassword(int32 RoomIndex, const FString& Password)
   277→{
   278→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   279→	if (!GameInstance || !GameInstance->GetSessionManager())
   280→	{
   281→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: GameInstance or SessionManager is null"));
   282→		return;
   283→	}
   284→
   285→	USessionManager* SessionManager = GameInstance->GetSessionManager();
   286→
   287→	// 세션에 저장된 비밀번호 추출
   288→	FString StoredPassword;
   289→	bool bHasPassword = SessionManager->GetSessionPassword(RoomIndex, StoredPassword);
   290→
   291→	if (bHasPassword && Password != StoredPassword)
   292→	{
   293→		// 비밀번호 불일치
   294→		UE_LOG(LogWjWorld, Warning, TEXT("RoomListWindow: Wrong password for room index %d"), RoomIndex);
   295→
   296→		if (PasswordInputWidgetInstance)
   297→		{
   298→			PasswordInputWidgetInstance->SetErrorMessage(FText::FromString(TEXT("Wrong password.")));
   299→		}
   300→		return;
   301→	}
   302→
   303→	// 비밀번호 일치 → 팝업 닫고 입장
   304→	if (PasswordInputWidgetInstance)
