    40→void URoomListEntryWidget::OnJoinClicked()
    41→{
    42→	UE_LOG(LogWjWorld, Log, TEXT("RoomListEntryWidget: Join button clicked - Room: %s (Private: %d)"),
    43→		*CurrentRoomInfo.RoomName, CurrentRoomInfo.bIsPrivate);
    44→
    45→	// 비공개 방이면 비밀번호 입력 팝업을 부모 RoomListWindow에 요청
    46→	if (CurrentRoomInfo.bIsPrivate)
    47→	{
    48→		// ScrollBox → RoomListWindow 계층으로 부모 탐색
    49→		URoomListWindow* RoomListWindow = nullptr;
    50→		UWidget* Parent = GetParent();
    51→		while (Parent)
    52→		{
    53→			// ScrollBox의 Outer를 통해 RoomListWindow 찾기
    54→			RoomListWindow = Cast<URoomListWindow>(Parent->GetTypedOuter<URoomListWindow>());
    55→			if (RoomListWindow)
    56→			{
    57→				break;
    58→			}
    59→			Parent = Parent->GetParent();
    60→		}
    61→
    62→		if (RoomListWindow)
    63→		{
    64→			RoomListWindow->RequestJoinPrivateRoom(CurrentRoomInfo.SearchResultIndex);
    65→			return;
    66→		}
    67→		else
    68→		{
    69→			UE_LOG(LogWjWorld, Error, TEXT("RoomListEntryWidget: Could not find parent RoomListWindow"));
    70→		}
    71→	}
    72→
    73→	// 공개 방 → 바로 입장
    74→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
    75→	if (GameInstance)
    76→	{
    77→		bool bSuccess = GameInstance->JoinRoom(CurrentRoomInfo.SearchResultIndex);
    78→		if (bSuccess)
    79→		{
    80→			UE_LOG(LogWjWorld, Log, TEXT("RoomListEntryWidget: Room join initiated"));
    81→
    82→			// 버튼 비활성화 (중복 클릭 방지)
    83→			if (JoinButton)
    84→			{
    85→				JoinButton->SetIsEnabled(false);
    86→			}
    87→		}
    88→		else
    89→		{
    90→			UE_LOG(LogWjWorld, Error, TEXT("RoomListEntryWidget: Failed to initiate room join"));
    91→		}
    92→	}
    93→	else
    94→	{
    95→		UE_LOG(LogWjWorld, Error, TEXT("RoomListEntryWidget: GameInstance is null"));
    96→	}
    97→}
