    24→void AWjWorldGameStateWaitingRoom::InitializeRoomSettings(const FRoomSettings& Settings)
    25→{
    26→	// Server Only
    27→	if (!HasAuthority())
    28→	{
    29→		UE_LOG(LogWjWorld, Warning, TEXT("GameStateWaitingRoom: InitializeRoomSettings called on non-authority"));
    30→		return;
    31→	}
    32→
    33→	RoomSettings = Settings;
    34→	OnRep_RoomSettings(); // 로컬에서도 이벤트 발생
    35→
    36→	// GameInstance에 방 설정 캐시 (호스트 마이그레이션용)
    37→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
    38→	{
    39→		GI->CacheRoomSettings(Settings);
    40→	}
    41→
    42→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Room settings initialized - %s"), *Settings.RoomName);
    43→}
