    45→void AWjWorldGameStateWaitingRoom::UpdateRoomSettings(const FRoomSettings& NewSettings)
    46→{
    47→	// Server Only
    48→	if (!HasAuthority())
    49→	{
    50→		UE_LOG(LogWjWorld, Warning, TEXT("GameStateWaitingRoom: UpdateRoomSettings called on non-authority"));
    51→		return;
    52→	}
    53→
    54→	// 변경된 내용 로그
    55→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Updating room settings - GameMode: %s -> %s, Map: %s -> %s"),
    56→		*RoomSettings.GameMode, *NewSettings.GameMode,
    57→		*RoomSettings.MapName, *NewSettings.MapName);
    58→
    59→	RoomSettings = NewSettings;
    60→	OnRep_RoomSettings(); // 로컬에서도 이벤트 발생
    61→
    62→	// GameInstance에도 캐시 업데이트 (호스트 마이그레이션용)
    63→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
    64→	{
    65→		GI->CacheRoomSettings(NewSettings);
    66→	}
    67→
    68→	// SessionManager에도 반영 (StartGame에서 사용)
    69→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
    70→	{
    71→		if (GI->GetSessionManager())
    72→		{
    73→			GI->GetSessionManager()->UpdateLastRoomSettings(NewSettings);
    74→		}
    75→	}
    76→}
