   142→bool AWjWorldGameStateWaitingRoom::AreAllPlayersReady() const
   143→{
   144→	// 유효한 플레이어 수 확인
   145→	int32 ValidPlayerCount = GetPlayerCount();
   146→	if (ValidPlayerCount == 0)
   147→	{
   148→		return false;
   149→	}
   150→
   151→	for (APlayerState* PS : PlayerArray)
   152→	{
   153→		AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PS);
   154→		if (WjPS && !WjPS->GetPlayerName().IsEmpty() && !WjPS->IsReady())
   155→		{
   156→			return false;
   157→		}
   158→	}
   159→
   160→	return true;
