   163→void AWjWorldGameStateWaitingRoom::OnRep_RoomSettings()
   164→{
   165→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Room settings replicated - %s"), *RoomSettings.RoomName);
   166→
   167→	// 클라이언트 측에서도 캐시 (호스트 마이그레이션용)
   168→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   169→	{
   170→		GI->CacheRoomSettings(RoomSettings);
   171→	}
   172→
   173→	// 클라이언트: 플레이어 목록도 캐시 (호스트 마이그레이션용)
   174→	BroadcastPlayerListChanged();
   175→
   176→	// 이벤트 브로드캐스트
   177→	OnRoomInfoChanged.Broadcast(RoomSettings);
