   253→void AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated(const FString& PlayerName)
   254→{
   255→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: OnPlayerNameUpdated called - %s"), *PlayerName);
   256→
   257→	// 플레이어 목록 재브로드캐스트
