    46→	}
    47→
    48→	// 배치 카탈로그 로드 (서버/클라이언트 모두)
    49→	LoadPlacementCatalog();
    50→
    51→	// 서버에서만 레이아웃 로드
    52→	if (HasAuthority())
    53→	{
    54→		LoadHostLayoutToGameState();
    55→	}
    56→
    57→	// ⭐ GameState 초기화 (Server Only)
    58→	if (HasAuthority())
    59→	{
    60→		UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
    61→		if (GameInstance)
    62→		{
    63→			// Safety: 이전 세션 상태가 InProgress면 종료 (게임 재시작 버그 방지)
    64→			GameInstance->EndGame();
    65→
    66→			AWjWorldGameStateWaitingRoom* WjGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
    67→
    68→			// 마이그레이션 후 진입인지 확인
    69→			bool bIsMigrationEntry = GameInstance->IsMigrating()
    70→				|| GameInstance->GetMigrationState() == EHostMigrationState::Complete;
    71→
    72→			if (bIsMigrationEntry && WjGameState)
    73→			{
    74→				// 마이그레이션 후 복구: 캐시된 방 설정 사용
    75→				const FRoomSettings& CachedSettings = GameInstance->GetMigrationContext().CachedRoomSettings;
    76→				WjGameState->InitializeRoomSettings(CachedSettings);
    77→
    78→				UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Migration recovery - restored room settings '%s'"),
    79→					*CachedSettings.RoomName);
    80→
    81→				// 마이그레이션 컨텍스트 리셋
    82→				GameInstance->GetMigrationContext().Reset();
    83→			}
    84→			else if (GameInstance->GetSessionManager() && WjGameState)
    85→			{
    86→				// 일반 진입: SessionManager에서 방 설정 가져오기
    87→				const FRoomSettings& Settings = GameInstance->GetSessionManager()->GetLastRoomSettings();
    88→				WjGameState->InitializeRoomSettings(Settings);
    89→
    90→				UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: GameState initialized with room settings"));
    91→			}
    92→			else
    93→			{
    94→				UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: Failed to initialize GameState"));
    95→			}
    96→		}
    97→		else
    98→		{
    99→			UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: GameInstance is null"));
   100→		}
   101→	}
   102→
   103→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: BeginPlay - WaitingRoom loaded"));
   104→}
