   145→void AWjWorldGameModePlay::Logout(AController* Exiting)
   146→{
   147→	// GameRule에 플레이어 이탈 알림 (Super::Logout 전에 호출해야 PlayerState가 유효함)
   148→	if (CurrentGameRule && Exiting)
   149→	{
   150→		AWjWorldPlayerStatePlay* ExitingPlayerState = Cast<AWjWorldPlayerStatePlay>(Exiting->PlayerState);
   151→		if (ExitingPlayerState)
   152→		{
   153→			UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout - Notifying GameRule for player %s"), *ExitingPlayerState->GetPlayerName());
   154→			CurrentGameRule->OnPlayerLeft(ExitingPlayerState);
   155→		}
   156→	}
   157→
   158→	Super::Logout(Exiting);
   159→
   160→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout completed for %s"), Exiting ? *Exiting->GetName() : TEXT("Unknown"));
   161→}
