   410→void UCreateRoomWindow::InitializeMapOptions()
   411→{
   412→	if (!MapComboBox)
   413→	{
   414→		return;
   415→	}
   416→
   417→	MapComboBox->ClearOptions();
   418→	MapOptionDisplayToValue.Empty();
   419→
   420→	FName CurrentGameModeId = NAME_None;
   421→
   422→	if (MinigameCatalog && GameModeComboBox)
   423→	{
   424→		FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   425→		if (const FName* GameModeId = GameModeDisplayToId.Find(SelectedGameMode))
   426→		{
   427→			CurrentGameModeId = *GameModeId;
   428→
   429→			if (const FWjWorldMinigameDefinition* Def = MinigameCatalog->FindByGameModeId(*GameModeId))
   430→			{
   431→				// 1. 기본 맵 옵션 추가
   432→				for (const FWjWorldMinigameMapOption& MapOption : Def->MapOptions)
   433→				{
   434→					FString DisplayStr = MapOption.DisplayName.ToString();
   435→					MapComboBox->AddOption(DisplayStr);
   436→					MapOptionDisplayToValue.Add(DisplayStr, MapOption.OptionValue);
   437→				}
   438→
   439→				// 첫 번째 항목 기본 선택
   440→				if (Def->MapOptions.Num() > 0)
   441→				{
   442→					MapComboBox->SetSelectedOption(Def->MapOptions[0].DisplayName.ToString());
   443→				}
   444→			}
   445→		}
   446→	}
   447→
   448→	// 2. 유저 커스텀 맵 옵션 추가
   449→	if (!CurrentGameModeId.IsNone())
   450→	{
   451→		AddUserMapOptions(CurrentGameModeId);
   452→	}
   453→
   454→	UE_LOG(LogWjWorld, Log, TEXT("CreateRoomWindow: Map options initialized (%d items)"), MapOptionDisplayToValue.Num());
   455→}
