   457→void UCreateRoomWindow::AddUserMapOptions(FName GameModeId)
   458→{
   459→	if (!MapComboBox)
   460→	{
   461→		return;
   462→	}
   463→
   464→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   465→	if (!DevSettings)
   466→	{
   467→		return;
   468→	}
   469→
   470→	// ApproachingWall: WallDescriptionDataAsset에서 유저 레이아웃 스캔
   471→	if (GameModeId == FName("ApproachingWall"))
   472→	{
   473→		if (!DevSettings->WallDescriptionAsset.IsNull())
   474→		{
   475→			UWjWorldWallDescriptionDataAsset* WallAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   476→			if (WallAsset)
   477→			{
   478→				TArray<FWjWorldWallDescription> UserLayouts;
   479→				int32 Count = WallAsset->ScanUserWallLayouts(UserLayouts);
   480→
   481→				for (const FWjWorldWallDescription& Layout : UserLayouts)
   482→				{
   483→					// "[User] 레이아웃명" 형식으로 표시 (WallName에서 User_ 접두사 제거)
   484→					FString DisplayName = Layout.WallName;
   485→					DisplayName.RemoveFromStart(TEXT("User_"));
   486→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   487→					MapComboBox->AddOption(DisplayStr);
   488→					// OptionValue는 WallName 그대로 (이미 User_ 접두사 포함)
   489→					MapOptionDisplayToValue.Add(DisplayStr, Layout.WallName);
   490→				}
   491→
   492→				if (Count > 0)
   493→				{
   494→					UE_LOG(LogWjWorld, Log, TEXT("CreateRoomWindow: Added %d user layouts for ApproachingWall"), Count);
   495→				}
   496→			}
   497→		}
   498→	}
   499→	else if (GameModeId == FName("JumpMap"))
   500→	{
   501→		if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
   502→		{
   503→			UJumpMapLayoutDataAsset* JumpMapAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
   504→			if (JumpMapAsset)
   505→			{
   506→				TArray<FJumpMapLayout> UserLayouts;
   507→				int32 Count = JumpMapAsset->ScanUserJumpMapLayouts(UserLayouts);
   508→
   509→				for (const FJumpMapLayout& Layout : UserLayouts)
   510→				{
   511→					FString DisplayName = Layout.LayoutName;
   512→					DisplayName.RemoveFromStart(TEXT("User_"));
   513→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   514→					MapComboBox->AddOption(DisplayStr);
   515→					MapOptionDisplayToValue.Add(DisplayStr, Layout.LayoutName);
   516→				}
   517→
   518→				if (Count > 0)
   519→				{
   520→					UE_LOG(LogWjWorld, Log, TEXT("CreateRoomWindow: Added %d user layouts for JumpMap"), Count);
   521→				}
   522→			}
   523→		}
   524→	}
   525→}
