   199→void AWjWorldGameStatePlay::OnRep_GameResult()
   200→{
   201→	if (!bGameResultReady) return;
   202→
   203→	UWorld* World = GetWorld();
   204→	if (!World) return;
   205→
   206→	APlayerController* PC = World->GetFirstPlayerController();
   207→	if (!PC) return;
   208→
   209→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   210→	if (!HUD) return;
   211→
   212→	FString LocalPlayerName;
   213→	if (PC->PlayerState)
   214→	{
   215→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   216→	}
   217→
   218→	FString ResultText;
   219→	if (bGameHasWinner)
   220→	{
   221→		if (LocalPlayerName == WinnerPlayerName)
   222→		{
   223→			ResultText = TEXT("Victory!");
   224→		}
   225→		else
   226→		{
   227→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   228→		}
   229→	}
   230→	else
   231→	{
   232→		ResultText = TEXT("Draw!");
   233→	}
   234→
   235→	HUD->ShowGameResultText(ResultText, 5.0f);
   236→
   237→	// 1인 플레이 시 스탯/보상 제외
   238→	const bool bShouldRecordStats = (InitialPlayerCount > 1);
   239→
   240→	// 스탯 기록 (각 클라이언트가 자신의 스탯만 기록)
   241→	// StatNamespace 기반 동적 스탯 키 생성
   242→	UWjWorldStatsSubsystem* Stats = GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   243→	if (bShouldRecordStats && Stats && PC->PlayerState && !StatNamespace.IsNone())
   244→	{
   245→		FString NS = StatNamespace.ToString();
   246→		Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_GamesPlayed"), *NS)));
   247→
   248→		if (bGameHasWinner && WinnerPlayerName == LocalPlayerName)
   249→		{
   250→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Wins"), *NS)));
   251→		}
   252→		else
   253→		{
   254→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Losses"), *NS)));
   255→		}
   256→
   257→		Stats->StoreStats();
   258→	}
   259→	else if (!bShouldRecordStats)
   260→	{
   261→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Skipping stats/rewards for solo play (InitialPlayerCount=%d)"), InitialPlayerCount);
   262→	}
   263→
   264→	// 재화 보상 지급 (각 클라이언트가 자신의 보상 요청)
   265→	UWjWorldCurrencySubsystem* CurrencySub = GetGameInstance()->GetSubsystem<UWjWorldCurrencySubsystem>();
   266→	if (bShouldRecordStats && CurrencySub && PC->PlayerState)
   267→	{
   268→		bool bIsLocalPlayerWinner = bGameHasWinner && (WinnerPlayerName == LocalPlayerName);
   269→		CurrencySub->TriggerMatchReward(bIsLocalPlayerWinner);
   270→	}
   271→
   272→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Result - %s"), *ResultText);
   273→}
