    99→bool USessionManager::CreateSession(const FRoomSettings& Settings)
   100→{
   101→	if (!SessionInterface.IsValid())
   102→	{
   103→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   104→		return false;
   105→	}
   106→
   107→	// ⭐ 중요: 기존 세션이 있다면 먼저 완전히 제거
   108→	auto ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   109→	if (ExistingSession != nullptr)
   110→	{
   111→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Existing session found. Destroying synchronously..."));
   112→		
   113→		SessionInterface->DestroySession(SESSION_NAME);
   114→		
   115→		int32 WaitCount = 0;
   116→		while (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr && WaitCount < 100)
   117→		{
   118→			FPlatformProcess::Sleep(0.01f);
   119→			WaitCount++;
   120→		}
   121→		
   122→		if (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr)
   123→		{
   124→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to destroy existing session"));
   125→			return false;
   126→		}
   127→		
   128→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Existing session destroyed successfully"));
   129→	}
   130→
   131→	// 네트워크 모드에 맞게 NetDriver 전환 (Listen Server가 올바른 드라이버 사용)
   132→	ApplyNetDriverForMode(Settings.NetworkMode);
   133→
   134→	// 세션 설정
   135→	FOnlineSessionSettings SessionSettings;
   136→	SessionSettings.NumPublicConnections = Settings.MaxPlayers;
   137→	SessionSettings.bShouldAdvertise = true;
   138→	SessionSettings.bAllowJoinInProgress = Settings.bAllowJoinInProgress;
   139→	SessionSettings.bAllowJoinViaPresence = false;
   140→	SessionSettings.bAllowJoinViaPresenceFriendsOnly = false;
   141→
   142→	// 네트워크 모드에 따른 설정
   143→	// Steam: bUsesPresence와 bUseLobbiesIfAvailable은 반드시 같은 값이어야 함
   144→	if (Settings.NetworkMode == ENetworkMode::Steam)
   145→	{
   146→		SessionSettings.bIsLANMatch = false;
   147→		SessionSettings.bUsesPresence = true;
   148→		SessionSettings.bUseLobbiesIfAvailable = true;
   149→	}
   150→	else // LAN
   151→	{
   152→		SessionSettings.bIsLANMatch = true;
   153→		SessionSettings.bUsesPresence = false;
   154→		SessionSettings.bUseLobbiesIfAvailable = false;
   155→	}
   156→
   157→	// 커스텀 데이터 설정
   158→	SessionSettings.Set(FName("ROOM_NAME"), Settings.RoomName, EOnlineDataAdvertisementType::ViaOnlineService);
   159→	SessionSettings.Set(FName("GAME_MODE"), Settings.GameMode, EOnlineDataAdvertisementType::ViaOnlineService);
   160→	SessionSettings.Set(FName("MAP_NAME"), Settings.MapName, EOnlineDataAdvertisementType::ViaOnlineService);
   161→	SessionSettings.Set(FName("IS_PRIVATE"), Settings.bIsPrivate, EOnlineDataAdvertisementType::ViaOnlineService);
   162→
   163→	if (Settings.bIsPrivate && !Settings.Password.IsEmpty())
   164→	{
   165→		SessionSettings.Set(FName("PASSWORD"), Settings.Password, EOnlineDataAdvertisementType::ViaOnlineService);
   166→	}
   167→
   168→	// 세션 생성 시도
   169→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   170→	bool bSuccess = SessionInterface->CreateSession(*LocalPlayer->GetPreferredUniqueNetId(), SESSION_NAME, SessionSettings);
   171→
   172→	if (bSuccess)
   173→	{
   174→		LastRoomSettings = Settings;
   175→		bIsHost = true;
   176→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Creating %s session '%s'"),
   177→			Settings.NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"),
   178→			*Settings.RoomName);
   179→	}
   180→	else
   181→	{
