   242→bool USessionManager::JoinSession(int32 RoomIndex)
   243→{
   244→	if (!SessionInterface.IsValid())
   245→	{
   246→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   247→		return false;
   248→	}
   249→
   250→	if (!SessionSearch.IsValid() || SessionSearch->SearchResults.Num() == 0)
   251→	{
   252→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: No search results available"));
   253→		return false;
   254→	}
   255→
   256→	if (!SessionSearch->SearchResults.IsValidIndex(RoomIndex))
   257→	{
   258→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Invalid room index %d"), RoomIndex);
   259→		return false;
   260→	}
   261→
   262→	// ⭐ 중요: 기존 세션이 있다면 먼저 제거
   263→	auto ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   264→	if (ExistingSession != nullptr)
   265→	{
   266→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Destroying existing session before joining..."));
   267→		
   268→		SessionInterface->DestroySession(SESSION_NAME);
   269→		
   270→		int32 WaitCount = 0;
   271→		while (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr && WaitCount < 100)
   272→		{
   273→			FPlatformProcess::Sleep(0.01f);
   274→			WaitCount++;
   275→		}
   276→		
   277→		if (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr)
   278→		{
   279→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to destroy existing session"));
   280→			return false;
   281→		}
   282→		
   283→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Existing session destroyed successfully"));
   284→	}
   285→
   286→	LastJoinedRoomIndex = RoomIndex;
   287→
   288→	// 선택된 세션에 참가
   289→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   290→	bool bSuccess = SessionInterface->JoinSession(*LocalPlayer->GetPreferredUniqueNetId(), SESSION_NAME, SessionSearch->SearchResults[RoomIndex]);
   291→
   292→	if (bSuccess)
   293→	{
   294→		bIsHost = false;
   295→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Joining session at index %d"), RoomIndex);
   296→	}
   297→	else
   298→	{
   299→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to join session"));
   300→	}
   301→
   302→	return bSuccess;
   303→}
