   407→void USessionManager::OnFindSessionsComplete(bool bWasSuccessful)
   408→{
   409→	bIsSearchInProgress = false;
   410→
   411→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnFindSessionsComplete - Success: %d"), bWasSuccessful);
   412→
   413→	// 대기 중인 검색 요청이 있으면 즉시 실행
   414→	if (PendingSearchRequest.IsSet())
   415→	{
   416→		ENetworkMode PendingMode = PendingSearchRequest.GetValue().Key;
   417→		int32 PendingMax = PendingSearchRequest.GetValue().Value;
   418→		PendingSearchRequest.Reset();
   419→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Executing pending %s search"),
   420→			PendingMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   421→		FindSessions(PendingMode, PendingMax);
   422→		return;
   423→	}
   424→
   425→	// 마이그레이션 세션 검색인 경우
   426→	if (!PendingMigrationTag.IsEmpty())
   427→	{
   428→		FString SearchTag = PendingMigrationTag;
   429→		PendingMigrationTag.Empty();
   430→
   431→		if (bWasSuccessful && SessionSearch.IsValid())
   432→		{
   433→			for (int32 i = 0; i < SessionSearch->SearchResults.Num(); i++)
   434→			{
   435→				FString FoundTag;
   436→				SessionSearch->SearchResults[i].Session.SessionSettings.Get(FName("MIGRATION_TAG"), FoundTag);
   437→
   438→				if (FoundTag == SearchTag)
   439→				{
   440→					UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Found migration session with tag '%s' at index %d"), *SearchTag, i);
   441→					JoinSession(i);
   442→					return;
   443→				}
   444→			}
   445→
   446→			UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Migration session with tag '%s' not found among %d results"),
   447→				*SearchTag, SessionSearch->SearchResults.Num());
   448→		}
   449→
   450→		// 마이그레이션 세션 미발견 → 빈 결과로 브로드캐스트하여 GameInstance가 재시도 처리
   451→		OnRoomsFoundEvent.Broadcast(false, TArray<FRoomInfo>());
   452→		return;
   453→	}
   454→
   455→	// 일반 세션 검색
   456→	TArray<FRoomInfo> Rooms;
   457→
   458→	if (bWasSuccessful && SessionSearch.IsValid())
   459→	{
   460→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Found %d sessions"), SessionSearch->SearchResults.Num());
   461→
   462→		for (int32 i = 0; i < SessionSearch->SearchResults.Num(); i++)
   463→		{
   464→			const FOnlineSessionSearchResult& Result = SessionSearch->SearchResults[i];
   465→
   466→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Session[%d] Details:"), i);
   467→			UE_LOG(LogWjWorld, Log, TEXT("  - IsValid: %d"), Result.IsValid());
   468→			UE_LOG(LogWjWorld, Log, TEXT("  - Ping: %d"), Result.PingInMs);
   469→			UE_LOG(LogWjWorld, Log, TEXT("  - NumPublicConnections: %d"), Result.Session.SessionSettings.NumPublicConnections);
   470→			UE_LOG(LogWjWorld, Log, TEXT("  - NumOpenPublicConnections: %d"), Result.Session.NumOpenPublicConnections);
   471→
   472→			FRoomInfo RoomInfo = ConvertSearchResultToRoomInfo(Result, i);
   473→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Room[%d] Name='%s' Mode='%s' Players=%d/%d"),
   474→				i, *RoomInfo.RoomName, *RoomInfo.GameMode,
   475→				RoomInfo.CurrentPlayers, RoomInfo.MaxPlayers);
   476→
   477→			Rooms.Add(RoomInfo);
   478→		}
   479→	}
   480→	else
   481→	{
   482→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: No sessions found or search failed"));
   483→	}
   484→
   485→	OnRoomsFoundEvent.Broadcast(bWasSuccessful, Rooms);
   486→}
