   717→	// 기본 정보
   718→	RoomInfo.SearchResultIndex = Index;
   719→	
   720→	// ⭐ 수정: 플레이어 수 계산
   721→	// NumOpenPublicConnections = 열린 슬롯 수
   722→	// 현재 플레이어 = 전체 - 열린 슬롯
   723→	int32 MaxPlayers = SearchResult.Session.SessionSettings.NumPublicConnections;
   724→	int32 OpenSlots = SearchResult.Session.NumOpenPublicConnections;
   725→	
   726→	RoomInfo.MaxPlayers = MaxPlayers;
   727→	RoomInfo.CurrentPlayers = MaxPlayers - OpenSlots;
   728→	
   729→	// ⭐ 최소 1명 보장 (호스트)
   730→	if (RoomInfo.CurrentPlayers <= 0)
   731→	{
   732→		RoomInfo.CurrentPlayers = 1;
   733→	}
   734→	
   735→	RoomInfo.Ping = SearchResult.PingInMs;
   736→
   737→	// 커스텀 데이터
   738→	SearchResult.Session.SessionSettings.Get(FName("ROOM_NAME"), RoomInfo.RoomName);
   739→	SearchResult.Session.SessionSettings.Get(FName("GAME_MODE"), RoomInfo.GameMode);
   740→	SearchResult.Session.SessionSettings.Get(FName("IS_PRIVATE"), RoomInfo.bIsPrivate);
   741→
   742→	// 호스트 이름
   743→	if (SearchResult.Session.OwningUserName.IsEmpty())
   744→	{
   745→		RoomInfo.HostName = TEXT("Unknown");
   746→	}
   747→	else
   748→	{
   749→		RoomInfo.HostName = SearchResult.Session.OwningUserName;
   750→	}
   751→
   752→	// 진행 상태
   753→	RoomInfo.bInProgress = SearchResult.Session.SessionSettings.bAllowJoinInProgress && (RoomInfo.CurrentPlayers > 0);
   754→
   755→	return RoomInfo;
   756→}
