   104→void AWjWorldGameModePlay::PostLogin(APlayerController* NewPlayer)
   105→{
   106→	Super::PostLogin(NewPlayer);
   107→
   108→	if (CurrentGameRule)
   109→	{
   110→		AWjWorldPlayerStatePlay* NewPlayerState = Cast<AWjWorldPlayerStatePlay>(NewPlayer->PlayerState);
   111→		if (NewPlayerState)
   112→		{
   113→			CurrentGameRule->OnPlayerJoined(NewPlayerState);
   114→		}
   115→	}
   116→
   117→	// Play 중 플레이어 목록 캐시 (호스트 마이그레이션용)
   118→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   119→	{
   120→		AGameStateBase* GS = GetGameState<AGameStateBase>();
   121→		if (GS)
   122→		{
   123→			TArray<FPlayerDisplayInfo> PlayerList;
   124→			bool bFirstPlayer = true;
   125→			for (APlayerState* PS : GS->PlayerArray)
   126→			{
   127→				if (PS && !PS->GetPlayerName().IsEmpty())
   128→				{
   129→					FPlayerDisplayInfo Info;
   130→					Info.PlayerName = PS->GetPlayerName();
   131→					Info.PlayerID = PS->GetPlayerId();
   132→					Info.bIsHost = bFirstPlayer; // 서버의 첫 번째 플레이어 = 호스트
   133→					Info.bIsReady = true;
   134→					PlayerList.Add(Info);
   135→					bFirstPlayer = false;
   136→				}
   137→			}
   138→			GI->CachePlayerList(PlayerList);
   139→		}
   140→	}
   141→
   142→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: PostLogin completed for %s"), *NewPlayer->GetName());
   143→}
   144→
   145→void AWjWorldGameModePlay::Logout(AController* Exiting)
   146→{
   147→	// GameRule에 플레이어 이탈 알림 (Super::Logout 전에 호출해야 PlayerState가 유효함)
   148→	if (CurrentGameRule && Exiting)
   149→	{
   150→		AWjWorldPlayerStatePlay* ExitingPlayerState = Cast<AWjWorldPlayerStatePlay>(Exiting->PlayerState);
   151→		if (ExitingPlayerState)
   152→		{
   153→			UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout - Notifying GameRule for player %s"), *ExitingPlayerState->GetPlayerName());
   154→			CurrentGameRule->OnPlayerLeft(ExitingPlayerState);
   155→		}
   156→	}
   157→
   158→	Super::Logout(Exiting);
   159→
   160→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout completed for %s"), Exiting ? *Exiting->GetName() : TEXT("Unknown"));
   161→}
   162→
   163→void AWjWorldGameModePlay::StartGame(float SecondsForStartCount)
   164→{
   165→	GetGameState<AWjWorldGameStatePlay>()->GameStartWithCountdown(SecondsForStartCount);
   166→	GetGameState<AWjWorldGameStatePlay>()->SetGameRuleClass(CurrentGameRule->GetClass());
   167→
   168→	if(GetWorld() && CurrentGameRule)
   169→	{
   170→		GetWorld()->GetTimerManager().SetTimer(StartGameHandle, FTimerDelegate::CreateLambda([this, SecondsForStartCount]()
   171→		{
   172→			CurrentGameRule->OnGameStart();
   173→			OnGameStart.Broadcast();
   174→		}), SecondsForStartCount, false);
   175→	}
   176→
   177→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartGame scheduled in %f seconds"), SecondsForStartCount);
   178→}
   179→
   180→void AWjWorldGameModePlay::EndGamePredict(float SecondsForEndCount)
   181→{
   182→	GetGameState<AWjWorldGameStatePlay>()->GameEndWithCountdown(SecondsForEndCount);
   183→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: EndGame scheduled in %f seconds"), SecondsForEndCount);
   184→}
