   186→void AWjWorldGameModePlay::OnGameLevelUp(int32 NewLevel)
   187→{
   188→	OnGameLevelChange.Broadcast(NewLevel);
   189→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Game Level Up to %d"), NewLevel);
   190→}
   191→
   192→void AWjWorldGameModePlay::BeginDestroy()
   193→{
   194→	Super::BeginDestroy();
   195→
   196→	UWorld* World = GetWorld();
   197→	if (World)
   198→	{
   199→		World->GetTimerManager().ClearTimer(StartGameHandle);
