    19→void UWjWorldGameRuleApproachingWall::Initialize(AWjWorldGameModePlay* InGameMode)
    20→{
    21→	Super::Initialize(InGameMode);
    22→
    23→	// DeveloperSettings에서 WallDescriptionAsset 로드
    24→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    25→	TSoftObjectPtr<UWjWorldWallDescriptionDataAsset> WallDescAsset;
