   143→void UWjWorldGameRuleApproachingWall::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   144→{
   145→	Super::OnPlayerJoined(Player);
   146→
   147→	if (!HasAuthority() || !Player) return;
   148→
   149→	// 플레이어를 생존자 목록에 추가
   150→	AlivePlayers.Add(Player);
   151→	AlivePlayerCount++;
   152→	TotalPlayerCount++;
   153→
   154→	UpdateGameData();
   155→
   156→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerJoined - Player: %s, Alive: %d, Total: %d"),
   157→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   158→}
