   538→void UWjWorldGameRuleApproachingWall::RecordKillStat(AWjWorldPlayerStatePlay* KillerPlayerState)
   539→{
   540→	if (!KillerPlayerState) return;
   541→
   542→	// 서버에서만 실행
   543→	if (!HasAuthority()) return;
   544→
   545→	// 킬러의 PlayerController를 통해 스탯 기록
   546→	APlayerController* KillerPC = Cast<APlayerController>(KillerPlayerState->GetOwner());
   547→	if (KillerPC && KillerPC->IsLocalController())
   548→	{
   549→		// 로컬 플레이어면 직접 기록
   550→		UWjWorldStatsSubsystem* Stats = GetWorld()->GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   551→		if (Stats)
   552→		{
   553→			Stats->IncrementLocalStat(WjWorldStats::ApproachingWall::Kills);
   554→			Stats->StoreStats();
   555→		}
   556→	}
   557→	// 원격 플레이어의 킬은 게임 종료 시 클라이언트에서 각자 처리하거나
   558→	// 별도 RPC로 처리해야 함 (현재는 로컬 플레이어만 즉시 기록)
   559→
   560→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::RecordKillStat - Recorded kill for %s"),
   561→		*KillerPlayerState->GetPlayerName());
   562→}
