   771→void UWjWorldGameRuleSumo::RemoveAllPlayerBuffs()
   772→{
   773→	for (const auto& WeakPS : AllPlayers)
   774→	{
   775→		if (!WeakPS.IsValid()) continue;
   776→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   777→
   778→		// PlayerState에서 ASC 가져오기 (ASC는 PlayerState에 있음)
   779→		UAbilitySystemComponent* ASC = PS->GetAbilitySystemComponent();
   780→		if (!ASC) continue;
   781→
   782→		// 紐⑤뱺 踰꾪봽 ?쒓렇 ?쒓굅
   783→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SpeedBoost());
   784→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SuperPush());
   785→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_Shield());
   786→
   787→		// State_Eliminated 태그 제거 (다음 라운드 어빌리티 활성화를 위해)
   788→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::State_Eliminated());
   789→
   790→		// 이동속도 복원 (기존 캐릭터가 존재하는 경우에만)
   791→		APawn* Pawn = PS->GetPawn();
   792→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   793→		if (Character)
   794→		{
   795→			if (UCharacterMovementComponent* MC = Character->GetCharacterMovement())
   796→			{
   797→				// 기본값으로 복원 (CDO에서)
   798→				MC->MaxWalkSpeed = Character->GetClass()->GetDefaultObject<ACharacter>()->GetCharacterMovement()->MaxWalkSpeed;
   799→			}
   800→		}
   801→	}
   802→}
