    45→void UWjWorldGameRuleJumpMap::LoadLayoutAndSpawnActors()
    46→{
    47→	UWorld* World = GetWorld();
    48→	if (!World) return;
    49→
    50→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    51→	if (!DevSettings) return;
    52→
    53→	// MapOption에서 레이아웃 이름 가져오기
    54→	FString MapOpt;
    55→	AWjWorldGameModePlay* GameModePlay = GetGameModePlay();
    56→	if (GameModePlay)
    57→	{
    58→		MapOpt = GameModePlay->GetMapOption();
    59→	}
    60→
    61→	// DataAsset에서 레이아웃 로드
    62→	bool bLayoutLoaded = false;
    63→	if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
    64→	{
    65→		UJumpMapLayoutDataAsset* LayoutAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
    66→		if (LayoutAsset)
    67→		{
    68→			FString LayoutName;
    69→
    70→			if (MapOpt.IsEmpty() || MapOpt.Equals(TEXT("Default"), ESearchCase::IgnoreCase))
    71→			{
    72→				// Default: BuiltInLayouts 첫 번째 레이아웃
    73→				if (LayoutAsset->BuiltInLayouts.Num() > 0)
    74→				{
    75→					LayoutName = LayoutAsset->BuiltInLayouts[0].LayoutName;
    76→				}
    77→			}
    78→			else if (MapOpt.Equals(TEXT("Random"), ESearchCase::IgnoreCase))
    79→			{
    80→				LayoutName = LayoutAsset->GetRandomLayoutName();
    81→			}
    82→			else
    83→			{
    84→				// 직접 지정된 레이아웃 이름 (유저 레이아웃 포함)
    85→				LayoutName = MapOpt;
    86→			}
    87→
    88→			if (!LayoutName.IsEmpty())
    89→			{
    90→				const FJumpMapLayout* Layout = LayoutAsset->GetLayoutByNameIncludingUser(LayoutName);
    91→				if (Layout)
    92→				{
    93→					SpawnActorsFromLayout(*Layout);
    94→					bLayoutLoaded = true;
    95→					UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Loaded layout '%s' (%d objects)"),
    96→						*LayoutName, Layout->Objects.Num());
    97→				}
    98→				else
    99→				{
   100→					UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: Layout '%s' not found"), *LayoutName);
   101→				}
   102→			}
   103→		}
   104→	}
   105→
   106→	if (!bLayoutLoaded)
   107→	{
   108→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Using map-placed actors (no layout loaded)"));
   109→	}
   110→
   111→	// 체크포인트/엔드 액터 수집 (CSV 로딩 후에도 실행하여 CheckpointLocations 갱신)
   112→	CheckpointLocations.Empty();
   113→	for (TActorIterator<AJumpMapCheckpointActor> It(World); It; ++It)
   114→	{
   115→		AJumpMapCheckpointActor* Checkpoint = *It;
   116→		if (Checkpoint)
   117→		{
   118→			int32 Order = Checkpoint->CheckpointOrder;
   119→			if (CheckpointLocations.Num() <= Order)
   120→			{
   121→				CheckpointLocations.SetNum(Order + 1);
   122→			}
   123→			CheckpointLocations[Order] = Checkpoint->GetActorLocation();
   124→
   125→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Checkpoint %d at %s"),
   126→				Order, *Checkpoint->GetActorLocation().ToString());
   127→		}
   128→	}
   129→
   130→	for (TActorIterator<AJumpMapEndActor> It(World); It; ++It)
   131→	{
   132→		AJumpMapEndActor* EndActor = *It;
   133→		if (EndActor)
   134→		{
   135→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: End actor at %s"),
   136→				*EndActor->GetActorLocation().ToString());
   137→		}
   138→	}
   139→
   140→	// 플레이어 스타트에서 시작 위치 가져오기
   141→	AActor* PlayerStart = UGameplayStatics::GetActorOfClass(World, APlayerStart::StaticClass());
   142→	if (PlayerStart)
   143→	{
   144→		StartLocation = PlayerStart->GetActorLocation();
   145→	}
   146→
   147→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Layout loaded - Start: %s, Checkpoints: %d"),
   148→		*StartLocation.ToString(), CheckpointLocations.Num());
   149→}
