   234→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Game Started - Players: %d, TimeLimit: %.1f"),
   235→		TotalPlayerCount, TimeLimit);
   236→
   237→	// 엣지 케이스: 플레이어 없음
   238→	if (TotalPlayerCount <= 0)
   239→	{
   240→		UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: No players, ending game"));
