   297→void UWjWorldGameRuleJumpMap::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   298→{
   299→	Super::OnPlayerJoined(Player);
   300→
   301→	if (!HasAuthority() || !Player) return;
   302→
   303→	AllPlayers.Add(Player);
   304→	TotalPlayerCount++;
   305→
   306→	UpdateGameData();
   307→
