   312→void UWjWorldGameRuleJumpMap::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   313→{
   314→	Super::OnPlayerLeft(Player);
   315→
   316→	if (!HasAuthority() || !Player) return;
   317→
   318→	AllPlayers.Remove(Player);
   319→	TotalPlayerCount--;
   320→
   321→	UpdateGameData();
   322→
   323→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Left - %s, Total: %d"),
   324→		*Player->GetPlayerName(), TotalPlayerCount);
   325→
   326→	// 모든 플레이어 이탈
   327→	if (TotalPlayerCount <= 0)
   328→	{
   329→		bGameOverConditionMet = true;
   330→		WinnerPlayer = nullptr;
   331→		OnGameEnd();
   332→		return;
   333→	}
   334→
   335→	// 남은 플레이어가 모두 완주했는지 체크
   336→	int32 ActivePlayers = 0;
   337→	for (const auto& WeakPS : AllPlayers)
   338→	{
   339→		if (!WeakPS.IsValid()) continue;
   340→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   341→		if (!PlayerData || !PlayerData->HasFinished())
   342→		{
   343→			ActivePlayers++;
   344→		}
   345→	}
   346→
   347→	if (ActivePlayers == 0 && FinishedPlayerCount > 0)
   348→	{
   349→		bGameOverConditionMet = true;
   350→		OnGameEnd();
   351→	}
   352→}
