   354→void UWjWorldGameRuleJumpMap::OnPlayerDied(AWjWorldCharacterPlay* Character)
   355→{
   356→	if (!HasAuthority() || !Character) return;
   357→
   358→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   359→	if (!PS) return;
   360→
   361→	// 이미 완주한 플레이어는 무시
   362→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   363→	if (!PlayerData || PlayerData->HasFinished()) return;
   364→
   365→	// 사망 횟수 증가
   366→	PlayerData->IncrementDeathCount();
   367→
   368→	int32 CheckpointIdx = PlayerData->GetCurrentCheckpointIndex();
   369→
   370→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player died: %s (Deaths: %d, Checkpoint: %d)"),
   371→		*PS->GetPlayerName(), PlayerData->GetDeathCount(), CheckpointIdx);
   372→
   373→	// 리스폰
   374→	RespawnPlayerAtCheckpoint(Character, CheckpointIdx);
   375→}
