   406→void UWjWorldGameRuleJumpMap::OnPlayerFinished(AWjWorldCharacterPlay* Character)
   407→{
   408→	if (!HasAuthority() || !Character) return;
   409→
   410→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   411→	if (!PS) return;
   412→
   413→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   414→	if (!PlayerData || PlayerData->HasFinished()) return;
   415→
   416→	// 완주 기록
   417→	PlayerData->SetFinished(ElapsedTime);
   418→	FinishedPlayerCount++;
   419→
   420→	// GameData에 완주 순서 추가
   421→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   422→	if (GameState)
   423→	{
   424→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   425→		if (GameData)
   426→		{
   427→			FJumpMapPlayerFinish FinishInfo;
   428→			FinishInfo.PlayerName = PS->GetPlayerName();
   429→			FinishInfo.FinishTime = ElapsedTime;
   430→			GameData->AddPlayerFinish(FinishInfo);
   431→			GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   432→		}
   433→	}
   434→
   435→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player finished: %s (Time: %.2f, Order: %d/%d)"),
   436→		*PS->GetPlayerName(), ElapsedTime, FinishedPlayerCount, TotalPlayerCount);
   437→
   438→	// 첫 번째 완주자가 승자
   439→	if (!WinnerPlayer.IsValid())
   440→	{
   441→		WinnerPlayer = PS;
   442→	}
   443→
   444→	// 모든 플레이어가 완주했는지 체크
   445→	int32 ActivePlayers = 0;
   446→	for (const auto& WeakPS : AllPlayers)
   447→	{
   448→		if (!WeakPS.IsValid()) continue;
   449→		UJumpMapPlayerDataComponent* PD = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   450→		if (!PD || !PD->HasFinished())
   451→		{
   452→			ActivePlayers++;
   453→		}
   454→	}
   455→
   456→	if (ActivePlayers == 0)
   457→	{
   458→		bGameOverConditionMet = true;
   459→		OnGameEnd();
   460→	}
   461→}
