   169→
   170→void UWjWorldGameInstance::HandleNetworkFailure(UWorld* World, UNetDriver* NetDriver,
   171→	ENetworkFailure::Type FailureType, const FString& ErrorString)
   172→{
   173→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleNetworkFailure called - Type: %d, Error: %s"),
   174→		static_cast<int32>(FailureType), *ErrorString);
   175→
   176→	// 이미 마이그레이션 중이면 무시
   177→	if (MigrationContext.bIsMigrating)
   178→	{
   179→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure ignored - already migrating"));
   180→		return;
   181→	}
   182→
   183→	// 자신이 호스트(서버)면 마이그레이션 불필요
   184→	if (World && World->GetAuthGameMode() != nullptr)
   185→	{
   186→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure on server - ignoring (Type: %d, Error: %s)"),
   187→			static_cast<int32>(FailureType), *ErrorString);
   188→		return;
   189→	}
   190→
   191→	// 게임 종료 후 WaitingRoom 복귀 중 호스트 퇴장 → 마이그레이션 없이 로비 복귀
   192→	if (bGameEndTraveling)
   193→	{
   194→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure during game-end travel - skipping migration, returning to lobby"));
   195→		bGameEndTraveling = false;
   196→		MigrationFailed();
   197→		return;
   198→	}
   199→
   200→	// 연결 관련 Failure 타입은 모두 마이그레이션 시도
   201→	// (Steam P2P에서는 다양한 에러 타입이 발생할 수 있음)
   202→	switch (FailureType)
   203→	{
   204→	case ENetworkFailure::ConnectionLost:
   205→	case ENetworkFailure::FailureReceived:
   206→	case ENetworkFailure::ConnectionTimeout:
   207→	case ENetworkFailure::PendingConnectionFailure:
   208→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure detected - Type: %d, Error: %s. Beginning host migration."),
   209→			static_cast<int32>(FailureType), *ErrorString);
   210→		BeginHostMigration();
   211→		break;
   212→	default:
   213→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure type %d not handled for migration"),
   214→			static_cast<int32>(FailureType));
   215→		break;
   216→	}
   217→}
   218→
   219→void UWjWorldGameInstance::HandleTravelFailure(UWorld* World, ETravelFailure::Type FailureType, const FString& ErrorString)
   220→{
   221→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleTravelFailure called - Type: %d, Error: %s"),
   222→		static_cast<int32>(FailureType), *ErrorString);
   223→
   224→	// 이미 마이그레이션 중이면 무시
   225→	if (MigrationContext.bIsMigrating)
   226→	{
   227→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure ignored - already migrating"));
   228→		return;
   229→	}
   230→
   231→	// 자신이 호스트(서버)면 마이그레이션 불필요
   232→	if (World && World->GetAuthGameMode() != nullptr)
   233→	{
   234→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure on server - ignoring"));
   235→		return;
   236→	}
   237→
   238→	// 게임 종료 후 WaitingRoom 복귀 중 호스트 퇴장 → 마이그레이션 없이 로비 복귀
   239→	if (bGameEndTraveling)
   240→	{
   241→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure during game-end travel - skipping migration, returning to lobby"));
   242→		bGameEndTraveling = false;
   243→		MigrationFailed();
   244→		return;
   245→	}
   246→
   247→	// ServerTravel 실패 시 호스트 마이그레이션 시도
   248→	switch (FailureType)
   249→	{
   250→	case ETravelFailure::ServerTravelFailure:
   251→	case ETravelFailure::ClientTravelFailure:
   252→	case ETravelFailure::TravelFailure:
   253→	case ETravelFailure::PackageMissing:
   254→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure detected - Type: %d. Beginning host migration."),
   255→			static_cast<int32>(FailureType));
   256→		BeginHostMigration();
   257→		break;
   258→	default:
   259→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure type %d not handled for migration"),
   260→			static_cast<int32>(FailureType));
   261→		break;
   262→	}
   263→}
