   265→// ============================================================================
   266→// 호스트 마이그레이션
   267→// ============================================================================
   268→
   269→void UWjWorldGameInstance::BeginHostMigration()
   270→{
   271→	MigrationContext.bIsMigrating = true;
   272→	MigrationContext.MigrationStartTime = FPlatformTime::Seconds();
   273→	MigrationContext.RetryCount = 0;
   274→	SetMigrationState(EHostMigrationState::Detected);
   275→
   276→	// 클라이언트: CachedPlayerList가 비어있으면 PlayerArray에서 직접 빌드
   277→	if (MigrationContext.CachedPlayerList.Num() == 0)
   278→	{
   279→		UWorld* World = GetWorld();
   280→		if (World)
   281→		{
   282→			if (AGameStateBase* GS = World->GetGameState())
   283→			{
   284→				for (APlayerState* PS : GS->PlayerArray)
   285→				{
   286→					if (PS)
   287→					{
   288→						FPlayerDisplayInfo Info;
   289→						Info.PlayerName = PS->GetPlayerName();
   290→						Info.PlayerID = PS->GetPlayerId();
   291→						MigrationContext.CachedPlayerList.Add(Info);
   292→					}
   293→				}
   294→			}
   295→
   296→			APlayerController* PC = UGameplayStatics::GetPlayerController(World, 0);
   297→			if (PC && PC->PlayerState)
   298→			{
   299→				MigrationContext.LocalPlayerID = PC->PlayerState->GetPlayerId();
   300→			}
   301→
   302→			UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Built player cache from PlayerArray - %d players (LocalID: %d)"),
   303→				MigrationContext.CachedPlayerList.Num(), MigrationContext.LocalPlayerID);
   304→		}
   305→	}
   306→
   307→	// SessionManager의 LastRoomSettings 동기화 (클라이언트에서 올바른 NetworkMode 사용)
   308→	if (SessionManager)
   309→	{
   310→		SessionManager->UpdateLastRoomSettings(MigrationContext.CachedRoomSettings);
   311→	}
   312→
   313→	// 마이그레이션 태그 생성 (모든 클라이언트 동일)
   314→	MigrationContext.MigrationSessionTag = GenerateMigrationTag();
   315→
   316→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Host migration started - Tag: '%s', NetworkMode: %s"),
   317→		*MigrationContext.MigrationSessionTag,
   318→		MigrationContext.CachedRoomSettings.NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   319→
   320→	// 기존 세션 파괴
   321→	if (SessionManager)
   322→	{
   323→		SessionManager->DestroySession();
   324→	}
   325→
   326→	// 타임아웃 타이머 설정
   327→	UWorld* World = GetWorld();
   328→	if (World)
   329→	{
   330→		World->GetTimerManager().SetTimer(MigrationTimeoutHandle,
   331→			FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::OnMigrationTimeout),
   332→			FHostMigrationContext::MigrationTimeout, false);
   333→	}
   334→
   335→	// 새 호스트 결정
   336→	MigrationContext.bIsNewHost = DetermineIfNewHost();
   337→
   338→	if (MigrationContext.bIsNewHost)
   339→	{
   340→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is the new host"));
   341→		MigrationCreateSession();
   342→	}
   343→	else
   344→	{
   345→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is NOT the new host - waiting 3s before searching"));
   346→
   347→		// 3초 대기 후 검색 시작
   348→		if (World)
   349→		{
   350→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   351→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   352→				3.0f, false);
   353→		}
   354→	}
   355→}
   356→
   357→bool UWjWorldGameInstance::DetermineIfNewHost() const
   358→{
   359→	const TArray<FPlayerDisplayInfo>& CachedPlayers = MigrationContext.CachedPlayerList;
   360→
   361→	if (CachedPlayers.Num() == 0)
   362→	{
   363→		// 캐시가 비어있으면 자신이 호스트
   364→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: No cached players - assuming new host"));
   365→		return true;
   366→	}
   367→
   368→	// PlayerID 오름차순 정렬 (이전 호스트 제외)
   369→	TArray<FPlayerDisplayInfo> Candidates;
   370→	for (const FPlayerDisplayInfo& Info : CachedPlayers)
   371→	{
   372→		if (!Info.bIsHost) // 이전 호스트 제외
   373→		{
   374→			Candidates.Add(Info);
   375→		}
   376→	}
   377→
   378→	if (Candidates.Num() == 0)
   379→	{
   380→		// 모든 플레이어가 호스트? 자신이 새 호스트
   381→		return true;
   382→	}
   383→
   384→	// PlayerID 오름차순 정렬
   385→	Candidates.Sort([](const FPlayerDisplayInfo& A, const FPlayerDisplayInfo& B)
   386→	{
   387→		return A.PlayerID < B.PlayerID;
   388→	});
   389→
   390→	// 첫 번째 = 새 호스트
   391→	return (Candidates[0].PlayerID == MigrationContext.LocalPlayerID);
   392→}
   393→
   394→FString UWjWorldGameInstance::GenerateMigrationTag() const
   395→{
   396→	// 결정론적 태그: "MIG_{RoomName}_{OriginalHostPlayerID}"
   397→	FString RoomName = MigrationContext.CachedRoomSettings.RoomName;
   398→	int32 OriginalHostID = -1;
   399→
   400→	for (const FPlayerDisplayInfo& Info : MigrationContext.CachedPlayerList)
   401→	{
   402→		if (Info.bIsHost)
   403→		{
   404→			OriginalHostID = Info.PlayerID;
   405→			break;
   406→		}
   407→	}
   408→
   409→	return FString::Printf(TEXT("MIG_%s_%d"), *RoomName, OriginalHostID);
   410→}
