   412→void UWjWorldGameInstance::MigrationCreateSession()
   413→{
   414→	SetMigrationState(EHostMigrationState::CreatingSession);
   415→
   416→	if (!SessionManager)
   417→	{
   418→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationCreateSession - SessionManager is null"));
   419→		MigrationFailed();
   420→		return;
   421→	}
   422→
   423→	// 콜백 바인딩
   424→	SessionManager->OnRoomCreatedEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   425→
   426→	bool bSuccess = SessionManager->CreateMigrationSession(
   427→		MigrationContext.CachedRoomSettings,
   428→		MigrationContext.MigrationSessionTag);
   429→
   430→	if (!bSuccess)
   431→	{
   432→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   433→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create migration session"));
   434→		MigrationRetryOrFail();
   435→	}
   436→}
