   438→void UWjWorldGameInstance::OnMigrationSessionCreated(bool bWasSuccessful)
   439→{
   440→	if (SessionManager)
   441→	{
   442→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   443→	}
   444→
   445→	if (bWasSuccessful)
   446→	{
   447→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session created - ServerTraveling to WaitingRoom"));
   448→		SetMigrationState(EHostMigrationState::Complete);
   449→
   450→		UWorld* World = GetWorld();
   451→		if (World)
   452→		{
   453→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   454→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   455→			World->ServerTravel(Settings->GetWaitingRoomOpenLevelURL());
   456→		}
   457→	}
   458→	else
   459→	{
   460→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration session creation failed"));
   461→		MigrationRetryOrFail();
   462→	}
   463→}
