   465→void UWjWorldGameInstance::MigrationSearchForNewHost()
   466→{
   467→	SetMigrationState(EHostMigrationState::SearchingSession);
   468→
   469→	if (!SessionManager)
   470→	{
   471→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationSearchForNewHost - SessionManager is null"));
   472→		MigrationFailed();
   473→		return;
   474→	}
   475→
   476→	// 콜백 바인딩
   477→	SessionManager->OnRoomsFoundEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   478→
   479→	bool bSuccess = SessionManager->FindMigrationSession(MigrationContext.MigrationSessionTag);
   480→
   481→	if (!bSuccess)
   482→	{
   483→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   484→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to start migration session search"));
   485→		MigrationRetryOrFail();
   486→	}
   487→}
   488→
   489→void UWjWorldGameInstance::OnMigrationSearchResult(bool bWasSuccessful, const TArray<FRoomInfo>& Rooms)
   490→{
   491→	if (SessionManager)
   492→	{
   493→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   494→	}
   495→
   496→	if (bWasSuccessful)
   497→	{
   498→		// JoinSession은 FindMigrationSession 내부에서 자동으로 호출됨
   499→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session found and joining"));
   500→		SetMigrationState(EHostMigrationState::JoiningSession);
   501→
   502→		UWorld* World = GetWorld();
   503→		if (World)
   504→		{
   505→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   506→		}
   507→		// JoinSession → ClientTravel이 자동으로 발생
   508→	}
   509→	else
   510→	{
   511→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration session not found - will retry"));
   512→		MigrationRetryOrFail();
   513→	}
   514→}
   515→
   516→void UWjWorldGameInstance::MigrationRetryOrFail()
   517→{
   518→	MigrationContext.RetryCount++;
   519→
   520→	// 타임아웃 체크
   521→	double ElapsedTime = FPlatformTime::Seconds() - MigrationContext.MigrationStartTime;
   522→	if (ElapsedTime >= FHostMigrationContext::MigrationTimeout)
   523→	{
   524→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timed out after %.1f seconds"), ElapsedTime);
   525→		MigrationFailed();
   526→		return;
   527→	}
   528→
   529→	// 최대 재시도 횟수 체크
   530→	if (MigrationContext.RetryCount >= FHostMigrationContext::MaxRetryCount)
   531→	{
   532→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration max retries (%d) reached"), FHostMigrationContext::MaxRetryCount);
   533→		MigrationFailed();
   534→		return;
   535→	}
   536→
   537→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration retry %d/%d in %.1f seconds"),
   538→		MigrationContext.RetryCount, FHostMigrationContext::MaxRetryCount, FHostMigrationContext::RetryInterval);
   539→
   540→	UWorld* World = GetWorld();
   541→	if (World)
   542→	{
   543→		if (MigrationContext.bIsNewHost)
   544→		{
   545→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   546→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationCreateSession),
   547→				FHostMigrationContext::RetryInterval, false);
   548→		}
   549→		else
   550→		{
   551→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   552→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   553→				FHostMigrationContext::RetryInterval, false);
   554→		}
   555→	}
   556→}
   557→
   558→void UWjWorldGameInstance::OnMigrationTimeout()
   559→{
   560→	UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timeout (%.0f seconds)"),
   561→		FHostMigrationContext::MigrationTimeout);
   562→	MigrationFailed();
   563→}
   564→
   565→void UWjWorldGameInstance::MigrationFailed()
   566→{
   567→	SetMigrationState(EHostMigrationState::Failed);
   568→
   569→	UWorld* World = GetWorld();
   570→	if (World)
   571→	{
   572→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   573→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
   574→	}
   575→
   576→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration failed - returning to lobby"));
   577→
   578→	// 세션 정리
   579→	if (SessionManager)
   580→	{
   581→		SessionManager->DestroySession();
   582→	}
   583→
   584→	// 마이그레이션 컨텍스트 리셋
   585→	MigrationContext.Reset();
   586→	bGameEndTraveling = false;
