   199→void AWjWorldGameStatePlay::OnRep_GameResult()
   200→{
   201→	if (!bGameResultReady) return;
   202→
   203→	UWorld* World = GetWorld();
   204→	if (!World) return;
   205→
   206→	APlayerController* PC = World->GetFirstPlayerController();
   207→	if (!PC) return;
   208→
   209→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   210→	if (!HUD) return;
   211→
   212→	FString LocalPlayerName;
   213→	if (PC->PlayerState)
   214→	{
   215→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   216→	}
   217→
   218→	FString ResultText;
   219→	if (bGameHasWinner)
   220→	{
   221→		if (LocalPlayerName == WinnerPlayerName)
   222→		{
   223→			ResultText = TEXT("Victory!");
   224→		}
   225→		else
   226→		{
   227→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   228→		}
   229→	}
   230→	else
   231→	{
   232→		ResultText = TEXT("Draw!");
   233→	}
   234→
   235→	HUD->ShowGameResultText(ResultText, 5.0f);
   236→
