   158→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   159→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   160→	{
   161→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   162→		if (Catalog)
   163→		{
   164→			const FWjWorldMinigameDefinition* MinigameDef = Catalog->FindByGameModeId(FName(*Settings.GameMode));
   165→			if (MinigameDef && WjGameState)
   166→			{
   167→				int32 PlayerCount = WjGameState->GetPlayerCount();
   168→				if (PlayerCount < MinigameDef->MinimumPlayers)
   169→				{
   170→					UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Not enough players (%d < %d) for %s"),
   171→						PlayerCount, MinigameDef->MinimumPlayers, *Settings.GameMode);
   172→					return;
   173→				}
   174→			}
   175→		}
   176→	}
   177→
   178→	// GameInstance를 통해 세션 시작
   179→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   180→	if (!GameInstance)
   181→	{
