   184→	}
   185→
   186→	bool bSuccess = GameInstance->StartGame();
   187→	if (!bSuccess)
   188→	{
   189→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: Failed to start session"));
