   196→		*Settings.GameMode, *Settings.MapName);
   197→
   198→	if (!WjGameState && GameInstance->GetSessionManager())
   199→	{
   200→		// 폴백: SessionManager에서 가져오기
   201→		Settings = GameInstance->GetSessionManager()->GetLastRoomSettings();
   202→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Fallback to SessionManager settings - GameMode: '%s', Map: '%s'"),
   203→			*Settings.GameMode, *Settings.MapName);
   204→	}
   205→
   206→	// 카탈로그에서 LevelPath 조회
   207→	FString TravelURL;
   208→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   209→	{
   210→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   211→		if (Catalog)
   212→		{
   213→			const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*Settings.GameMode));
   214→			if (Def)
   215→			{
   216→				// LevelPath + GameMode 명시적 지정 + GameModeId 전달 (GameRule 조회용)
   217→				TravelURL = DevSettings->GetPlayServerTravelURL(Def->LevelPath, Settings.GameMode);
