   219→				// MapOption을 URL 옵션으로 전달
   220→				if (!Settings.MapName.IsEmpty())
   221→				{
   222→					TravelURL += FString::Printf(TEXT("?MapOption=%s"), *Settings.MapName);
   223→				}
   224→
   225→				UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Travel to '%s' (GameModeId: %s)"),
   226→					*TravelURL, *Settings.GameMode);
   227→			}
   228→			else
   229→			{
   230→				UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: GameModeId '%s' not found in catalog"), *Settings.GameMode);
   231→			}
   232→		}
   233→	}
   234→
   235→	// 폴백: 카탈로그에서 못 찾으면 기본 경로 사용
   236→	if (TravelURL.IsEmpty())
   237→	{
   238→		TravelURL = TEXT("/Game/Map/03-1_ApproachingWall");
   239→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Using fallback travel URL: %s"), *TravelURL);
   240→	}
