	 * 게임 종료 래퍼. Play → WaitingRoom 복귀 전에 호출.
	 * @return 성공 여부
	 */
	UFUNCTION(BlueprintCallable, Category = "Session")
	bool EndGame();

	/** 게임 종료 후 WaitingRoom 복귀 중임을 표시 (클라이언트 OnRep_GamePhase에서 호출) */
	void MarkGameEndTraveling() { bGameEndTraveling = true; }

	//~ 캐싱 (호스트 마이그레이션용)
