	/** 방 설정 캐시 */
	void CacheRoomSettings(const FRoomSettings& Settings);

	//~ 호스트 마이그레이션
	/** 마이그레이션 진행 중 여부 */
	UFUNCTION(BlueprintPure, Category = "Migration")
	bool IsMigrating() const { return MigrationContext.bIsMigrating; }

